using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace UnityAgentBridge
{
    /// <summary>
    /// Dynamic C# execution: writes a temporary editor script, lets Unity compile it and
    /// reads the result back from the job store. The generated file deletes itself.
    /// </summary>
    public static class DynamicCommands
    {
        const string Template = @"// <auto-generated> Unity Agent Bridge dynamic job {{JOB}}. Deletes itself after running.
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using Object = UnityEngine.Object;

namespace UnityAgentBridgeGenerated
{
    public static class {{CLASS}}
    {
        [InitializeOnLoadMethod]
        private static void __BridgeEntry()
        {
            UnityAgentBridge.JobRunner.Execute(""{{JOB}}"", __UserCode);
        }

        private static object __UserCode()
        {
{{CODE}}
            return null;
        }
    }
}
";

        public static void Register()
        {
            CommandRegistry.Register("cs.execute", "执行一段 C# 代码（方法体，可 return 任意值）。会触发一次脚本编译+域重载，返回 jobId 后需用 cs.status 轮询", "code, jobId?",
                delegate(Dictionary<string, object> args)
                {
                    BridgeSettings settings = BridgeSettingsStore.Load();
                    if (!settings.allowRemoteCode)
                        throw new CommandException("远程代码执行已被禁用（Tools/Unity Agent Bridge 里勾选 Allow remote code）", "forbidden");

                    string code = J.Str(args, "code");
                    if (string.IsNullOrEmpty(code))
                        throw new CommandException("缺少 code", "bad_request");

                    if (EditorApplication.isCompiling)
                        throw new CommandException("Unity 正在编译，请稍后重试", "compiling");

                    string jobId = SanitizeJobId(J.Str(args, "jobId"));
                    string className = "DynamicJob_" + jobId;
                    string assetPath = JobRunner.GeneratedAssetPath(jobId);

                    string source = Template
                        .Replace("{{JOB}}", jobId)
                        .Replace("{{CLASS}}", className)
                        .Replace("{{CODE}}", Indent(code, new string(' ', 12)));

                    BridgePaths.EnsureDirectories();
                    string fullPath = JobRunner.FullPath(assetPath);
                    Directory.CreateDirectory(Path.GetDirectoryName(fullPath));

                    // Remove a stale result from a previous run with the same id.
                    string resultPath = JobRunner.ResultPath(jobId);
                    if (File.Exists(resultPath)) File.Delete(resultPath);

                    File.WriteAllText(fullPath, source, new UTF8Encoding(false));

                    // Compiling here would kill the in-flight response, so let the next editor
                    // update tick trigger the import. Clients should poll cs.status afterwards.
                    EditorApplication.delayCall += delegate { AssetDatabase.Refresh(); };

                    return new Dictionary<string, object>
                    {
                        { "jobId", jobId },
                        { "className", className },
                        { "assetPath", assetPath },
                        { "status", "scheduled" },
                        { "hint", "用 cs.status {jobId} 轮询结果；编译失败可用 cs.discard 清理" }
                    };
                });

            CommandRegistry.Register("cs.status", "查询动态代码任务的执行结果", "jobId",
                delegate(Dictionary<string, object> args)
                {
                    string jobId = SanitizeJobId(CommandRegistry.Require(args, "jobId"));
                    string resultPath = JobRunner.ResultPath(jobId);

                    if (File.Exists(resultPath))
                    {
                        Dictionary<string, object> payload = null;
                        try
                        {
                            payload = J.AsDict(Json.Parse(File.ReadAllText(resultPath)));
                        }
                        catch (Exception e)
                        {
                            return new Dictionary<string, object>
                            {
                                { "jobId", jobId },
                                { "status", "corrupt" },
                                { "error", "结果文件解析失败: " + e.Message }
                            };
                        }

                        if (payload != null)
                        {
                            payload["status"] = J.Bool(payload, "ok", false) ? "done" : "failed";
                            return payload;
                        }

                        return new Dictionary<string, object> { { "jobId", jobId }, { "status", "corrupt" } };
                    }

                    bool pending = File.Exists(JobRunner.FullPath(JobRunner.GeneratedAssetPath(jobId)));
                    var errors = BridgeLog.CompileErrors(10);
                    var errorList = new List<object>();
                    for (int i = 0; i < errors.Count; i++) errorList.Add(BridgeLog.ToDict(errors[i]));

                    return new Dictionary<string, object>
                    {
                        { "jobId", jobId },
                        { "status", pending ? "pending" : "unknown" },
                        { "isCompiling", EditorApplication.isCompiling },
                        { "compileFailed", EditorUtility.scriptCompilationFailed },
                        { "errors", errorList }
                    };
                });

            CommandRegistry.Register("cs.list", "列出最近的动态代码任务结果", "limit?=20",
                delegate(Dictionary<string, object> args)
                {
                    int limit = Mathf.Clamp(J.Int(args, "limit", 20), 1, 200);
                    var list = new List<object>();
                    if (Directory.Exists(BridgePaths.JobsDir))
                    {
                        var files = Directory.GetFiles(BridgePaths.JobsDir, "*.result.json");
                        Array.Sort(files, delegate(string a, string b) { return File.GetLastWriteTimeUtc(b).CompareTo(File.GetLastWriteTimeUtc(a)); });
                        for (int i = 0; i < files.Length && i < limit; i++)
                        {
                            var info = new Dictionary<string, object> { { "jobId", Path.GetFileName(files[i]).Replace(".result.json", "") } };
                            try
                            {
                                var payload = J.AsDict(Json.Parse(File.ReadAllText(files[i])));
                                info["ok"] = J.Bool(payload, "ok", false);
                                info["finishedAt"] = J.Str(payload, "finishedAt");
                                info["error"] = J.Str(payload, "error");
                            }
                            catch (Exception)
                            {
                                info["ok"] = null;
                            }
                            list.Add(info);
                        }
                    }
                    return new Dictionary<string, object> { { "count", list.Count }, { "jobs", list } };
                });

            CommandRegistry.Register("cs.discard", "丢弃某个任务：删除它生成的脚本和结果（编译失败时用）", "jobId",
                delegate(Dictionary<string, object> args)
                {
                    string jobId = SanitizeJobId(CommandRegistry.Require(args, "jobId"));
                    bool deleted = false;

                    string assetPath = JobRunner.GeneratedAssetPath(jobId);
                    if (File.Exists(JobRunner.FullPath(assetPath)))
                    {
                        AssetDatabase.DeleteAsset(assetPath);
                        deleted = true;
                    }

                    string resultPath = JobRunner.ResultPath(jobId);
                    if (File.Exists(resultPath)) { File.Delete(resultPath); deleted = true; }

                    if (deleted) AssetDatabase.Refresh();
                    return new Dictionary<string, object> { { "jobId", jobId }, { "deleted", deleted } };
                });

            CommandRegistry.Register("cs.clean", "清空动态代码目录与全部任务结果", "",
                delegate(Dictionary<string, object> args)
                {
                    int removed = 0;

                    string folder = BridgePaths.GeneratedFolderAssetPath;
                    if (AssetDatabase.IsValidFolder(folder))
                    {
                        foreach (string guid in AssetDatabase.FindAssets("", new[] { folder }))
                        {
                            string path = AssetDatabase.GUIDToAssetPath(guid);
                            if (path.EndsWith(".cs", StringComparison.OrdinalIgnoreCase))
                            {
                                AssetDatabase.DeleteAsset(path);
                                removed++;
                            }
                        }
                    }

                    int results = 0;
                    if (Directory.Exists(BridgePaths.JobsDir))
                    {
                        foreach (string file in Directory.GetFiles(BridgePaths.JobsDir, "*.json"))
                        {
                            try { File.Delete(file); results++; }
                            catch (Exception) { /* ignored */ }
                        }
                    }

                    AssetDatabase.Refresh();
                    return new Dictionary<string, object> { { "scripts", removed }, { "results", results } };
                });
        }

        static string Indent(string code, string pad)
        {
            string normalized = code.Replace("\r\n", "\n").Replace('\r', '\n');
            string[] lines = normalized.Split('\n');
            var builder = new StringBuilder(code.Length + lines.Length * pad.Length);
            for (int i = 0; i < lines.Length; i++)
            {
                if (i > 0) builder.Append('\n');
                string line = lines[i];
                if (line.Length == 0) continue;
                builder.Append(pad).Append(line);
            }
            return builder.ToString();
        }

        public static string SanitizeJobId(string id)
        {
            if (string.IsNullOrEmpty(id))
                return "j" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + "_" + Guid.NewGuid().ToString("N").Substring(0, 6);

            var builder = new StringBuilder(id.Length + 1);
            for (int i = 0; i < id.Length; i++)
            {
                char c = id[i];
                if (char.IsLetterOrDigit(c) || c == '_') builder.Append(c);
            }
            if (builder.Length == 0) builder.Append("job");
            if (!char.IsLetter(builder[0])) builder.Insert(0, 'j');
            if (builder.Length > 64) return builder.ToString(0, 64);
            return builder.ToString();
        }
    }
}
